shared_html.shared_css:
/* ============ SHARED HEADER ============ */
.site-nav {
  background: var(--surface);
  color: var(--text);
  border-bottom: 2px solid var(--accent);
  font-family: 'Eczar', Georgia, serif;
  position: relative;
}

.site-nav__topband {
  height: 14px;
  background:
    repeating-linear-gradient(
      90deg,
      var(--primary) 0 28px,
      var(--accent) 28px 32px,
      var(--secondary) 32px 60px,
      var(--accent) 60px 64px
    );
  border-bottom: 1px solid var(--accent);
}

.site-nav__inner {
  max-width: 1180px;
  margin: 0 auto;
  padding: 1.4rem 2rem 1.1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.9rem;
}

.site-nav__brand { display: flex; flex-direction: column; align-items: center; gap: 0.35rem; }

.site-nav__kicker {
  font-family: 'Cinzel', serif;
  font-size: 0.72rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--secondary);
}

.site-nav__wordmark {
  text-decoration: none;
  color: var(--text-emphasis);
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1.1;
}

.site-nav__line1 {
  font-family: 'Cinzel', serif;
  font-weight: 700;
  font-size: clamp(1.6rem, 3.4vw, 2.4rem);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-emphasis);
}

.site-nav__seal {
  color: var(--primary);
  font-size: 0.9rem;
  margin: 0.15rem 0;
}

.site-nav__line2 {
  font-family: 'Cinzel', serif;
  font-weight: 500;
  font-size: 0.78rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--secondary);
}

.site-nav__menu ul {
  list-style: none;
  margin: 0;
  padding: 0.4rem 0 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0;
}

.site-nav__menu li { position: relative; }

.site-nav__menu li + li::before {
  content: "❖";
  color: var(--accent);
  margin: 0 0.2rem;
  font-size: 0.7rem;
  vertical-align: middle;
}

.site-nav__menu a {
  display: inline-block;
  padding: 0.45rem 0.9rem;
  font-family: 'Cinzel', serif;
  font-size: 0.82rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--text);
  transition: color 0.2s, background 0.2s;
}

.site-nav__menu a:hover {
  color: var(--surface);
  background: var(--primary);
}

.site-nav__rule {
  display: flex;
  justify-content: center;
  gap: 0.55rem;
  padding: 0.55rem 0;
  background: var(--primary);
  border-top: 1px solid var(--accent);
  border-bottom: 3px double var(--accent);
}

.site-nav__rule span {
  width: 12px;
  height: 12px;
  background: var(--accent);
  transform: rotate(45deg);
  box-shadow: inset 0 0 0 2px var(--primary);
}

/* ============ SHARED FOOTER ============ */
.site-footer {
  background: var(--secondary);
  color: var(--surface);
  font-family: 'Eczar', Georgia, serif;
  margin-top: 4rem;
  border-top: 4px double var(--accent);
}

.site-footer__rule {
  display: flex;
  justify-content: center;
  gap: 0.55rem;
  padding: 0.7rem 0;
  background: var(--primary);
  border-bottom: 2px solid var(--accent);
}

.site-footer__rule span {
  width: 14px;
  height: 14px;
  background: var(--accent);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
}

.site-footer__arcade {
  max-width: 1180px;
  margin: 0 auto;
  padding: 2.4rem 2rem 1.4rem;
  display: grid;
  grid-template-columns: 1fr 1.2fr 1fr;
  gap: 1.5rem;
  text-align: center;
  position: relative;
}

.site-footer__arcade::before,
.site-footer__arcade::after {
  content: "";
  position: absolute;
  top: 1.4rem;
  bottom: 1rem;
  width: 14px;
  background:
    linear-gradient(var(--accent), var(--accent)) center/4px 100% no-repeat,
    linear-gradient(var(--surface), var(--surface));
  border: 2px solid var(--accent);
}
.site-footer__arcade::before { left: 33.33%; }
.site-footer__arcade::after  { left: 66.66%; }

.site-footer__pillar h4 {
  font-family: 'Cinzel', serif;
  font-size: 0.82rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 0.7rem;
  border-bottom: 1px solid var(--accent);
  padding-bottom: 0.4rem;
}

.site-footer__pillar p {
  margin: 0.3rem 0;
  font-size: 0.95rem;
  line-height: 1.55;
  color: var(--surface);
}

.site-footer__phone {
  font-family: 'Cinzel', serif;
  letter-spacing: 0.18em;
  color: var(--accent) !important;
  font-size: 0.85rem !important;
}

.site-footer__pillar--center {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.site-footer__mandala {
  position: relative;
  width: 110px;
  height: 110px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.site-footer__mandala-ring {
  position: absolute;
  inset: 0;
  border: 2px solid var(--accent);
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 50%, transparent 38%, var(--primary) 38% 42%, transparent 42%),
    conic-gradient(from 0deg, var(--primary) 0 30deg, transparent 30deg 60deg, var(--primary) 60deg 90deg, transparent 90deg 120deg, var(--primary) 120deg 150deg, transparent 150deg 180deg, var(--primary) 180deg 210deg, transparent 210deg 240deg, var(--primary) 240deg 270deg, transparent 270deg 300deg, var(--primary) 300deg 330deg, transparent 330deg);
}

.site-footer__mandala-ring--inner {
  inset: 22px;
  border: 1px solid var(--accent);
  background: var(--surface);
  box-shadow: inset 0 0 0 4px var(--secondary), inset 0 0 0 5px var(--accent);
}

.site-footer__mandala-glyph {
  position: relative;
  z-index: 2;
  font-size: 1.8rem;
  color: var(--text-emphasis);
  font-weight: 700;
}

.site-footer__motto {
  font-family: 'Cinzel', serif;
  font-size: 0.78rem !important;
  letter-spacing: 0.18em;
  color: var(--accent) !important;
  line-height: 1.6 !important;
}
.site-footer__motto em {
  font-family: 'Eczar', serif;
  font-style: italic;
  letter-spacing: 0.04em;
  text-transform: none;
  color: var(--surface) !important;
  font-size: 0.85rem;
}

.site-footer__nav {
  text-align: center;
  padding: 1.2rem 1rem;
  border-top: 1px solid var(--accent);
  border-bottom: 1px solid var(--accent);
  background: rgba(0,0,0,0.18);
}

.site-footer__nav a {
  font-family: 'Cinzel', serif;
  font-size: 0.78rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--accent);
  text-decoration: none;
  padding: 0 0.5rem;
}

.site-footer__nav a:hover { color: var(--surface); }

.site-footer__nav span {
  color: var(--primary);
  font-size: 0.8rem;
}

.site-footer__colophon {
  max-width: 880px;
  margin: 0 auto;
  padding: 1.3rem 2rem 1.8rem;
  text-align: center;
}

.site-footer__colophon p {
  margin: 0;
  font-size: 0.82rem;
  line-height: 1.6;
  color: var(--surface);
  font-style: italic;
}

/* ============ RESPONSIVE ============ */
@media (max-width: 760px) {
  .site-nav__menu ul { flex-direction: column; gap: 0; }
  .site-nav__menu li + li::before { display: none; }
  .site-nav__menu a { display: block; padding: 0.5rem 1rem; }
  .site-footer__arcade { grid-template-columns: 1fr; }
  .site-footer__arcade::before,
  .site-footer__arcade::after { display: none; }
  .site-footer__nav a { display: inline-block; padding: 0.3rem 0.5rem; }
}
